const D = { energy: .6, density: .55, scale: 1, speed: 1, wear: .5, tilt: .5, hue: 42, x: .5, y: .5, style: 'oiled', act: 'read', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const md = (a, n) => ((a % n) + n) % n;
// integer hash — finalize with >>> (>> sign-extends and caps the hash at 0.5)
function h2(ix, iy) { let h = (ix * 374761393 + iy * 668265263 + (P.seed | 0) * 1442695041) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967295; }
function h1(i) { return h2(i | 0, 0x6d1f); }

const en = clp(P.energy, 0, 1), dens = clp(P.density, 0, 1), wear = clp(P.wear, 0, 1);
const W = width, H = height, u = Math.min(W, H);
const hs = P.hue - 42;

const ST = {
  oiled:   { deck:[150,22,17], tape:[41,30,60], edge:[34,36,38], hole:[30,50,7],  lamp:[42,88,99], metal:[40,10,44], txt:[44,26,72], glow:.9 },
  manila:  { deck:[24,14,24],  tape:[38,34,58], edge:[30,40,36], hole:[26,52,8],  lamp:[36,84,97], metal:[32,12,50], txt:[36,28,68], glow:.7 },
  xray:    { deck:[206,54,13], tape:[202,34,30], edge:[200,30,22], hole:[196,10,92], lamp:[192,66,98], metal:[204,26,40], txt:[198,16,84], glow:1 },
  fanfold: { deck:[268,26,14], tape:[268,10,54], edge:[268,16,34], hole:[268,30,8], lamp:[300,70,96], metal:[268,10,42], txt:[280,14,72], glow:.5 }
};
const st = ST[P.style] || ST.oiled;
const DEH = md(st.deck[0] + hs, 360), TAH = md(st.tape[0] + hs, 360), EDH = md(st.edge[0] + hs, 360), HOH = md(st.hole[0] + hs, 360), LAH = md(st.lamp[0] + hs, 360), MEH = md(st.metal[0] + hs, 360), TXH = md(st.txt[0] + hs, 360);
const neg = P.style === 'xray';

// ---- the program on the tape: an infinite procedural byte stream ----
const WORDS = ['LOAD','STOR','JMP ','ADD ','SUB ','SHFT','ROT ','NAND','HALT','READ','PNCH','TAPE','CORE','ACC ','IDX ','LINK'];
let ent = 0.5 + dens * 0.5, runs = 1;
if (P.act === 'header') { ent = 0.12; runs = 3; }        // long leader runs + sprocket-only stretches
else if (P.act === 'scramble') { ent = 1; runs = 0; }
function byteAt(i) {
  if (runs && md(Math.floor(i / 96), 5) === 0) return i % 2 ? 0x00 : 0x7f;   // leader / trailer runs
  const r = h1(i * 3 + 1);
  if (r > ent) { const w = WORDS[Math.floor(h1(i * 3 + 2) * WORDS.length)]; return w.charCodeAt(md(i, 4)) & 0x7f; }
  return Math.floor(h1(i * 3 + 5) * 128) & 0x7f;
}
function chAt(i) { const b = byteAt(i); return (b >= 32 && b < 127) ? String.fromCharCode(b) : '·'; }

// ---- tape geometry: a diagonal run across the deck, head at the middle ----
const sc = clp(P.scale, .35, 2.2);
const ang = (clp(P.tilt, 0, 1) - .5) * 0.62;             // tape run angle
const TW = 0.30 * u * sc;                                // tape width (8 tracks + sprocket)
const PITCH = TW * 0.115;                                // hole pitch along the tape
const cx = P.x * W, cy = P.y * H;
const feed = K.t * (2.4 + clp(P.speed, 0, 3) * 6.2) * PITCH * 8;   // px/s along the tape
const dc = drawingContext;

// ---- cached deck plate + tape stock texture ----
const pkey = P.style + '|' + Math.round(P.hue) + '|' + (P.seed | 0) + '|' + wear.toFixed(2);
if (!S.deck || S.pkey !== pkey) {
  if (S.deck && S.deck.remove) S.deck.remove();
  if (S.stock && S.stock.remove) S.stock.remove();
  const g = createGraphics(384, 288); g.pixelDensity(1); g.colorMode(g.HSB, 360, 100, 100, 100);
  g.noStroke(); g.background(DEH, st.deck[1], st.deck[2]);
  for (let i = 0; i < 1500; i++) {                       // crackle enamel / cast texture
    g.fill(DEH, st.deck[1] * (.7 + h1(i * 2 + 3)), st.deck[2] * (h1(i * 2 + 4) > .5 ? 1.45 : .6), 10);
    g.ellipse(h1(i * 2 + 5) * 384, h1(i * 2 + 6) * 288, 2 + h1(i * 2 + 7) * 9, 2 + h1(i * 2 + 8) * 7);
  }
  for (let i = 0; i < 140; i++) {                        // oil bloom + wear patches
    g.fill(DEH, st.deck[1] * 1.5, st.deck[2] * (h1(i * 3 + 11) > .5 ? 1.6 : .5), 4 + h1(i * 3 + 12) * 10 * wear);
    g.ellipse(h1(i * 3 + 13) * 384, h1(i * 3 + 14) * 288, 20 + h1(i * 3 + 15) * 90 * wear, 14 + h1(i * 3 + 16) * 60 * wear);
  }
  S.deck = g;
  const s2 = createGraphics(256, 64); s2.pixelDensity(1); s2.colorMode(s2.HSB, 360, 100, 100, 100);
  s2.noStroke(); s2.background(TAH, st.tape[1], st.tape[2]);
  for (let i = 0; i < 1800; i++) {                       // paper fibre + oil staining
    s2.fill(TAH, st.tape[1] * (.6 + h1(i * 2 + 21) * .9), st.tape[2] * (h1(i * 2 + 22) > .5 ? 1.22 : .74), 11);
    s2.rect(h1(i * 2 + 23) * 256, h1(i * 2 + 24) * 64, 3 + h1(i * 2 + 25) * 14, 1);
  }
  for (let i = 0; i < 60; i++) {
    s2.fill(TAH, st.tape[1] * 1.7, st.tape[2] * .68, 5 + h1(i * 3 + 31) * 9 * wear);
    s2.ellipse(h1(i * 3 + 32) * 256, h1(i * 3 + 33) * 64, 10 + h1(i * 3 + 34) * 50 * wear, 6 + h1(i * 3 + 35) * 22 * wear);
  }
  S.stock = s2; S.pkey = pkey;
}

// =================== deck ===================
noStroke();
background(DEH, st.deck[1], st.deck[2] * .6);
image(S.deck, 0, 0, W, H);
// a broad raking light across the deck — slow, incommensurate, carries the motion floor
blendMode(ADD);
const sweep = md(K.t * 0.037, 1);
for (let i = 0; i < 7; i++) { noStroke(); fill(LAH, 14, 100, 2.4);
  push(); translate((sweep * 1.7 - .35) * W, H * .5); rotate(-0.42);
  rect(-u * .09 + i * u * .028, -H, u * .024, H * 2); pop(); }
blendMode(BLEND);

// ---- reels: feed (left) and take-up (right), turning at radius-dependent rates ----
function reel(rx, ry, rad, spin, full) {
  noStroke();
  fill(MEH, st.metal[1] * .8, st.metal[2] * .45); ellipse(rx, ry, rad * 2.16);
  fill(TAH, st.tape[1] * .9, st.tape[2] * .62); ellipse(rx, ry, rad * 2 * full);   // wound tape
  for (let k = 0; k < 26; k++) {                                                    // wound layers
    noFill(); stroke(TAH, st.tape[1], st.tape[2] * (k % 2 ? .5 : .78), 40); strokeWeight(1);
    ellipse(rx, ry, rad * 2 * full * (0.42 + 0.58 * k / 26));
  }
  noStroke(); fill(MEH, st.metal[1] * .6, st.metal[2] * 1.35); ellipse(rx, ry, rad * .78);
  push(); translate(rx, ry); rotate(spin);
  for (let k = 0; k < 3; k++) {                                                     // hub spokes
    push(); rotate(k * TAU / 3);
    fill(MEH, st.metal[1] * .5, st.metal[2] * 1.7); rect(-rad * .055, -rad * .36, rad * .11, rad * .36, 2);
    pop();
  }
  fill(MEH, st.metal[1] * .4, st.metal[2] * 2.0); ellipse(0, 0, rad * .20);
  pop();
  noFill(); stroke(MEH, st.metal[1] * .5, st.metal[2] * 1.5, 60); strokeWeight(Math.max(1, u * .0016));
  ellipse(rx, ry, rad * 2.16);
}
const rr = u * .17 * sc;
// radii breathe on long incommensurate cycles — the reels never "run out" (no convergence)
const fullA = 0.58 + 0.30 * Math.sin(K.t * 0.021), fullB = 0.58 + 0.30 * Math.sin(K.t * 0.021 + Math.PI);
const rlx = cx - Math.cos(ang) * u * .40 * sc, rly = cy - Math.sin(ang) * u * .40 * sc;
const rrx = cx + Math.cos(ang) * u * .40 * sc, rry = cy + Math.sin(ang) * u * .40 * sc;
reel(rlx, rly, rr, -feed / (rr * fullA), fullA);
reel(rrx, rry, rr, feed / (rr * fullB), fullB);

// ---- the tape: a band running corner to corner through the head ----
push();
translate(cx, cy);
rotate(ang);
const L = u * sc * 0.80 + rr * 2.2;   // reel-to-reel, so column count is scale-invariant
// stock, tiled along the run
dc.save(); dc.beginPath(); dc.rect(-L * .5, -TW * .5, L, TW); dc.clip();
const tileW = TW * 4;
const off = md(-feed, tileW);
for (let x = -L * .5 + off - tileW; x < L * .5; x += tileW) image(S.stock, x, -TW * .5, tileW, TW);
// edges: the tape's darkened, worn margins
noStroke();
fill(EDH, st.edge[1], st.edge[2], 70); rect(-L * .5, -TW * .5, L, TW * .055); rect(-L * .5, TW * .445, L, TW * .055);

// ---- the read window: a backlit slot; light pours through every hole ----
const winW = TW * 1.35;
blendMode(BLEND);
fill(LAH, st.lamp[1] * .25, st.lamp[2], 16 * (0.5 + en));
rect(-winW * .5, -TW * .5, winW, TW);

// ---- holes ----
const i0 = Math.floor((feed - L * .5) / PITCH) - 1, i1 = Math.floor((feed + L * .5) / PITCH) + 1;
const TRK = 8, sprkT = 3;      // sprocket sits between tracks 3 and 4, and is smaller
const trkY = t => (t + (t >= sprkT ? 1 : 0) + 1) / (TRK + 2) * TW * .84 - TW * .42;
const holeR = TW * .052, sprkR = TW * .022;
for (let i = i0; i <= i1; i++) {
  const x = i * PITCH - feed;
  if (x < -L * .5 - PITCH || x > L * .5 + PITCH) continue;
  const inWin = Math.abs(x) < winW * .5;
  const b = byteAt(i);
  // sprocket hole: always present, the tape's heartbeat
  noStroke();
  fill(HOH, st.hole[1], st.hole[2], neg ? 30 : 92);
  ellipse(x, (sprkT + 1) / (TRK + 2) * TW * .84 - TW * .42, sprkR * 2);
  if (inWin) { blendMode(ADD); fill(LAH, st.lamp[1] * .5, 100, 46 * st.glow); ellipse(x, (sprkT + 1) / (TRK + 2) * TW * .84 - TW * .42, sprkR * 2.9); blendMode(BLEND); }
  for (let t = 0; t < TRK; t++) {
    if (!((b >> t) & 1)) continue;
    const y = trkY(t);
    noStroke(); fill(HOH, st.hole[1], st.hole[2], neg ? 24 : 94);
    ellipse(x, y, holeR * 2);
    if (inWin) {                       // photocell lamp shines through
      blendMode(ADD);
      fill(LAH, st.lamp[1] * .45, 100, 62 * st.glow * (0.5 + en * .6));
      ellipse(x, y, holeR * 2.0);
      fill(LAH, st.lamp[1] * .7, 100, 15 * st.glow);
      ellipse(x, y, holeR * 4.4);
      blendMode(BLEND);
    }
  }
}
// tape sheen: a specular band along the run
blendMode(ADD); noStroke();
fill(0, 0, 100, 4 + 3 * en); rect(-L * .5, -TW * .30, L, TW * .10);
blendMode(BLEND);
dc.restore();

// ---- read head: the gate, guide rollers, lamp housing ----
noStroke();
fill(MEH, st.metal[1] * .7, st.metal[2] * .5, 92);
rect(-winW * .5 - u * .012, -TW * .78, u * .012, TW * 1.56, 2);
rect(winW * .5, -TW * .78, u * .012, TW * 1.56, 2);
fill(MEH, st.metal[1] * .5, st.metal[2] * 1.5, 84);
rect(-winW * .5, -TW * .78, winW, u * .010);
rect(-winW * .5, TW * .78 - u * .010, winW, u * .010);
for (let s2 = -1; s2 <= 1; s2 += 2) {   // guide rollers
  const rx = s2 * winW * .78;
  fill(MEH, st.metal[1] * .6, st.metal[2] * .9); ellipse(rx, -TW * .60, u * .030);
  fill(MEH, st.metal[1] * .4, st.metal[2] * 1.8);
  push(); translate(rx, -TW * .60); rotate(feed / (u * .015) * s2);
  rect(-u * .002, -u * .012, u * .004, u * .024, 1); pop();
}
pop();

// ---- decoded ASCII scrolling out of the head — text as the instrument's voice ----
textFont('Courier New');
const cur = Math.floor(feed / PITCH);
const nCh = 26;
let asc = '', hex = '';
for (let k = -nCh; k <= 0; k++) { asc += chAt(cur + k); hex += byteAt(cur + k).toString(16).padStart(2, '0') + ' '; }
noStroke(); textAlign(LEFT, TOP);
fill(TXH, st.txt[1], st.txt[2] * .3, 62);
rect(u * .026, H - u * .105, u * .55, u * .078, 3);
textSize(clp(u * .019, 8, 34)); fill(LAH, st.lamp[1] * .35, st.lamp[2], 94);
text(asc, u * .036, H - u * .098);
textSize(clp(u * .0105, 5, 18)); fill(TXH, st.txt[1], st.txt[2], 62);
text(hex.slice(-3 * 26), u * .036, H - u * .070);
fill(TXH, st.txt[1], st.txt[2] * .8, 56);
text('FRAME ' + String(md(cur, 1000000)).padStart(6, '0') + '   8-TRACK  ·  ' + Math.round((2.4 + clp(P.speed, 0, 3) * 6.2) * 8) + ' ch/s   ' + P.act.toUpperCase(), u * .036, H - u * .050);

// placard
textAlign(LEFT, TOP); textSize(clp(u * .016, 8, 30)); fill(TXH, st.txt[1], st.txt[2], 88);
text('TAPE READER  ·  PHOTOELECTRIC', u * .030, u * .028);
textSize(clp(u * .0105, 5, 18)); fill(TXH, st.txt[1], st.txt[2] * .8, 66);
text('SPROCKET LOCK   LAMP OK   TENSION NOM', u * .030, u * .050);

blendMode(BLEND);
noFill(); stroke(0, 0, 0, 30); strokeWeight(u * .10); rect(-u * .05, -u * .05, W + u * .1, H + u * .1);
dc.shadowBlur = 0;
blendMode(BLEND);
if (P.alpha < 100) { noStroke(); fill(DEH, st.deck[1], st.deck[2] * .6, 100 - clp(P.alpha, 0, 100)); rect(0, 0, W, H); }
